#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int N=5e5+5,M=505;
const ll INF=1e18;
int c,n,m,d,q;
int w[N];
ll dis[M][M],ans;
vector<pair<int,int>> f[N];

void read(int &x){
    x=0;
    char ch=getchar();
    while(ch<'0'||ch>'9')ch=getchar();
    while(ch>='0'&&ch<='9')x=x*10+(ch^48),ch=getchar();
}

int main(){
    read(c);read(n);read(m);read(d);read(q);
    for(int i=1;i<=m;i++)read(w[i]);
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++)dis[i][j]=(i==j?0:INF);
        int k;
        read(k);
        for(int j=1;j<=k;j++){
            int a,t;
            read(a);read(t);
            f[a].push_back({i,t});
            for(int x=0;x<(int)f[a].size();x++){
                int u=f[a][x].first;
                dis[i][u]=dis[u][i]=min(dis[u][i],(ll)t+f[a][x].second);
            }
        }
    }
    // 线路图上 Floyd：dis[i][j] = 从线路 i 换到线路 j 的最少步行时间
    for(int k=1;k<=n;k++)
        for(int i=1;i<=n;i++)
            for(int j=1;j<=n;j++)
                dis[i][j]=min(dis[i][j],dis[i][k]+dis[k][j]);
    while(q--){
        int a,b;
        read(a);read(b);
        ans=INF;
        for(int i=0;i<(int)f[a].size();i++)
            for(int j=0;j<(int)f[b].size();j++){
                auto p=f[a][i],r=f[b][j];
                ans=min(ans,dis[p.first][r.first]+p.second+r.second+w[a]+w[b]);
            }
        printf("%lld\n",ans);
    }
    return 0;
}
